contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address receiver, uint256 amount) public {
        require(receiver != address(0), "receiver zero");
        require(amount > 0, "amount zero");

        (uint128 beforeUsdc,
         uint128 beforeUnclaimed,
         uint256 beforeRound) = c.userDeposits(receiver);

        uint256 beforeShares = c.unclaimedShares(receiver);

        uint256 expected = uint256(beforeUnclaimed);
        uint256 expectedUsdc = 0;
        if (beforeRound < c.currentRound() && beforeUsdc > 0) {
            (uint128 roundUsdc, uint128 roundShares) = c.roundDeposits(beforeRound);
            expected += uint256(beforeUsdc) * uint256(roundShares) / uint256(roundUsdc);
            expectedUsdc = uint256(beforeUsdc);
        }

        assert(beforeShares == expected && beforeShares >= uint256(beforeUnclaimed) && beforeShares >= uint256(beforeUsdc) && expectedUsdc <= uint256(beforeUsdc));
    }
}

