contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address receiver) public payable {
        require(amount > 0 && amount <= type(uint128).max);
        require(receiver != address(0));

        uint256 initialUnclaimed = c.unclaimedShares(receiver);
        uint256 initialUsdcBalance = c.usdcBalance(receiver);
        uint256 initialRound = c.currentRound();

        (bool successDeposit, ) = address(c).call(
            abi.encodeWithSignature("depositUsdc(uint256,address)", amount, receiver)
        );
        // If deposit fails (e.g., transferFrom fails), the rule we want to check is vacuously true; we only assert after success.
        if (!successDeposit) {
            assert(true);
            return;
        }

        uint256 afterUsdcBalance = c.usdcBalance(receiver);
        uint256 afterUnclaimed = c.unclaimedShares(receiver);
        uint256 afterRound = c.currentRound();

        uint256 claimedShares = 0;
        uint256 sharesTransferred = c.balanceOf(receiver);
        uint256 vaultBalance = c.balanceOf(address(this));

        assert(
            afterRound == initialRound &&
            afterUsdcBalance + afterUnclaimed + sharesTransferred <= initialUsdcBalance + initialUnclaimed + vaultBalance + amount
        );
    }

    receive() external payable {}
}

