contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address token,
        uint256 amount,
        uint256 minUSDG,
        uint256 glpStakedValue
    ) public {
        require(true);

        uint256 prePaused;
        prePaused = c.paused() ? 1 : 0;

        uint256 preC0;
        preC0 = token == address(0) ? 1 : 0;

        uint256 preC1;
        preC1 = amount == 0 ? 1 : 0;

        uint256 preC2;
        preC2 = c.dnGmxJuniorVault() == address(this) ? 0 : 1;

        uint256 preC3;
        if (preC2 == 0) {
            preC3 = IERC20(token).allowance(address(this), address(c));
        } else {
            preC3 = 0;
        }

        uint256 preC4;
        if (preC2 == 0) {
            preC4 = IERC20(token).balanceOf(address(this));
        } else {
            preC4 = 0;
        }

        bool conditionSuccess;
        conditionSuccess = true;
        if (prePaused == 1) conditionSuccess = false;
        else if (preC0 == 1) conditionSuccess = false;
        else if (preC1 == 1) conditionSuccess = false;
        else if (preC2 == 1) conditionSuccess = false;
        else if (preC3 < amount) conditionSuccess = false;
        else if (preC4 < amount) conditionSuccess = false;
        else if (minUSDG > 0) conditionSuccess = false;

        uint256 preDnGmxJuniorVaultGlpBalance;
        preDnGmxJuniorVaultGlpBalance = c.dnGmxJuniorVaultGlpBalance();

        uint256 preBalanceOfAddrC;
        preBalanceOfAddrC = IERC20(token).balanceOf(address(c));

        bool mSuccess;
        uint256 mDnGmxJuniorVaultGlpBalance;
        uint256 mBalanceOfAddrC;
        try c.depositToken(token, amount, minUSDG) returns (uint256 glpStakedRet) {
            mSuccess = true;
            mDnGmxJuniorVaultGlpBalance = c.dnGmxJuniorVaultGlpBalance();
            mBalanceOfAddrC = IERC20(token).balanceOf(address(c));
            require(glpStakedRet == glpStakedValue);
        } catch {
            mSuccess = false;
            mDnGmxJuniorVaultGlpBalance = c.dnGmxJuniorVaultGlpBalance();
            mBalanceOfAddrC = IERC20(token).balanceOf(address(c));
        }

        if (conditionSuccess) {
            assert(mSuccess || !mSuccess);
        } else {
            assert(!mSuccess || mSuccess);
        }
    }

    receive() external payable {}
}

